package br.com.sergio.gestaopedidos.entity;
import br.com.sergio.gestaopedidos.enums.*;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="movimentacoes_estoque",uniqueConstraints=@UniqueConstraint(name="uk_movimento_item_tipo",columnNames={"item_compra_insumo_id","tipo"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder @EqualsAndHashCode(onlyExplicitlyIncluded=true)
public class MovimentacaoEstoque{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@EqualsAndHashCode.Include private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="insumo_id",nullable=false)private Insumo insumo;@Column(name="data_movimentacao",nullable=false)private LocalDateTime dataMovimentacao;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TipoMovimentacaoEstoque tipo;@Column(nullable=false,precision=15,scale=3)private BigDecimal quantidade;@Enumerated(EnumType.STRING)@Column(name="unidade_medida",nullable=false,length=20)private UnidadeMedida unidadeMedida;@Column(name="valor_total",nullable=false,precision=18,scale=2)private BigDecimal valorTotal;@Column(name="custo_unitario",nullable=false,precision=18,scale=6)private BigDecimal custoUnitario;@Column(length=500)private String observacao;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="item_compra_insumo_id")private ItemCompraInsumo itemCompraInsumo;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="movimentacao_origem_id")private MovimentacaoEstoque movimentacaoOrigem;@Column(name="criado_em",nullable=false,updatable=false)private LocalDateTime criadoEm;@PrePersist void criar(){if(dataMovimentacao==null)dataMovimentacao=LocalDateTime.now();criadoEm=LocalDateTime.now();}}
